const input = $('Parse Inbox').first().json;
const resp = $input.first().json;
const raw = resp?.content?.[0]?.text || '';

const synthesisMd = `---
type: daily-synthesis
date: ${input.date}
generated: ${new Date().toISOString()}
---

# Síntesis Diaria — ${input.date}

${raw}

---

## 📎 Backlinks
- [[Daily-Inbox]]
- [[PROJECTS/ZENTI]]
- [[PROJECTS/Charly.io]]

#síntesis-diaria
`;

const filename = `${input.date}-sintesis.md`;
const filepath = `SYNTHESIS/${filename}`;

return [{
  json: {
    status: 'ok',
    date: input.date,
    filename,
    filepath,
    synthesisMd
  }
}];
